package com.atlashub.pay.ledger.presentation.rest;import com.atlashub.pay.ledger.application.commands.TransferBetweenAccounts.*;import com.atlashub.pay.ledger.presentation.dto.*;import com.atlashub.shared.application.dto.ApiResponse;import com.atlashub.shared.application.security.AuthenticatedPrincipal;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/pay/account-transfers")public class AccountTransferController{private final TransferBetweenAccountsHandler handler;public AccountTransferController(TransferBetweenAccountsHandler h){handler=h;}@PostMapping public ResponseEntity<ApiResponse<AccountTransferResponse>> transfer(@AuthenticationPrincipal AuthenticatedPrincipal p,@Valid @RequestBody TransferBetweenAccountsRequest r){var x=handler.execute(new TransferBetweenAccountsCommand(p.activeOrganizationId(),p.userId(),p.environment(),r.sourceAccountId(),r.destinationAccountId(),r.amount(),r.currency(),r.reference(),r.description()));return ResponseEntity.ok(new ApiResponse<>(true,"Transfer posted",new AccountTransferResponse(x.transactionId(),x.reference(),x.postedAt()),null));}}
